// src/App.js
import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import './App.css';

// Components
import Header from './components/Header/Header';
import Footer from './components/Footer/Footer';
import Login from './components/Login/Login';
import Register from './components/Register/Register';
import ProtectedRoute from './components/Protected/ProtectedRoute';

// Utils
import { getUser, clearAuthData } from './utils/auth';

// You'll need to create these components
// import Home from './components/Home/Home';
// import Profile from './components/Profile/Profile';
// import MyBookings from './components/Bookings/MyBookings';
// etc...

function App() {
  const user = getUser();

  const handleLogout = () => {
    clearAuthData();
    window.location.href = '/login';
  };

  return (
    <BrowserRouter>
      <div className="App">
        {/* Header - shown on all pages except login/register */}
        <Routes>
          <Route
            path="/*"
            element={
              window.location.pathname !== '/login' &&
              window.location.pathname !== '/register' ? (
                <Header
                  user={user}
                  role={user?.role === 'receptionist' || user?.role === 'admin' ? 'receptionist' : 'guest'}
                  onLogout={handleLogout}
                />
              ) : null
            }
          />
        </Routes>

        {/* Main Content */}
        <main style={{ flex: 1, minHeight: 'calc(100vh - 200px)' }}>
          <Routes>
            {/* Public Routes */}
            <Route path="/" element={<Navigate to="/home" replace />} />
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
            
            {/* Public Pages (you need to create these) */}
            {/* <Route path="/home" element={<Home />} />
            <Route path="/rooms" element={<Rooms />} />
            <Route path="/guidelines" element={<Guidelines />} />
            <Route path="/rules" element={<Rules />} /> */}

            {/* Protected Customer Routes */}
            <Route
              path="/profile"
              element={
                <ProtectedRoute allowedRoles={['customer', 'admin', 'receptionist']}>
                  {/* <Profile /> */}
                  <div>Profile Page - To be implemented</div>
                </ProtectedRoute>
              }
            />
            
            <Route
              path="/my-bookings"
              element={
                <ProtectedRoute allowedRoles={['customer', 'admin']}>
                  {/* <MyBookings /> */}
                  <div>My Bookings Page - To be implemented</div>
                </ProtectedRoute>
              }
            />
            
            <Route
              path="/user/requests"
              element={
                <ProtectedRoute allowedRoles={['customer', 'admin']}>
                  {/* <MyRequests /> */}
                  <div>My Requests Page - To be implemented</div>
                </ProtectedRoute>
              }
            />

            {/* Protected Receptionist Routes */}
            <Route
              path="/receptionist/booking-list"
              element={
                <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
                  {/* <BookingList /> */}
                  <div>Booking List - To be implemented</div>
                </ProtectedRoute>
              }
            />
            
            <Route
              path="/receptionist/create-booking"
              element={
                <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
                  {/* <CreateBooking /> */}
                  <div>Create Booking - To be implemented</div>
                </ProtectedRoute>
              }
            />
            
            <Route
              path="/receptionist/room-fees"
              element={
                <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
                  {/* <RoomFees /> */}
                  <div>Room Fees - To be implemented</div>
                </ProtectedRoute>
              }
            />
            
            <Route
              path="/receptionist/bills"
              element={
                <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
                  {/* <Bills /> */}
                  <div>Bills - To be implemented</div>
                </ProtectedRoute>
              }
            />
            
            <Route
              path="/receptionist/rules"
              element={
                <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
                  {/* <Rules /> */}
                  <div>Rules Management - To be implemented</div>
                </ProtectedRoute>
              }
            />
            
            <Route
              path="/receptionist/rooms"
              element={
                <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
                  {/* <RoomsManagement /> */}
                  <div>Rooms Management - To be implemented</div>
                </ProtectedRoute>
              }
            />

            {/* Protected Admin Routes */}
            <Route
              path="/admin/users"
              element={
                <ProtectedRoute allowedRoles={['admin']}>
                  {/* <UserManagement /> */}
                  <div>User Management - To be implemented</div>
                </ProtectedRoute>
              }
            />

            {/* Error Pages */}
            <Route
              path="/unauthorized"
              element={
                <div style={{ padding: '50px', textAlign: 'center' }}>
                  <h1>403 - Unauthorized</h1>
                  <p>You don't have permission to access this page.</p>
                </div>
              }
            />
            
            <Route
              path="*"
              element={
                <div style={{ padding: '50px', textAlign: 'center' }}>
                  <h1>404 - Page Not Found</h1>
                  <p>The page you're looking for doesn't exist.</p>
                </div>
              }
            />
          </Routes>
        </main>

        {/* Footer - shown on all pages except login/register */}
        <Routes>
          <Route
            path="/*"
            element={
              window.location.pathname !== '/login' &&
              window.location.pathname !== '/register' ? (
                <Footer />
              ) : null
            }
          />
        </Routes>
      </div>
    </BrowserRouter>
  );
}

export default App;
